mapper.select:
select user_id, balance_amount, frozen_amount from member_wallets where user_id in
#{memberId}
order by user_id for update

select user_id, balance_amount, frozen_amount
from member_wallets
where user_id = #{memberId}

mapper.update:
update member_wallets
set balance_amount = #{balanceAmount},
    frozen_amount = #{frozenAmount}
where user_id = #{memberId}

mapper.insert:
insert into wallet_ledgers (
  user_id, type, amount, balance_before, balance_after, frozen_before, frozen_after, remark
) values (
  #{memberId}, #{type}, #{amount}, #{balanceBefore}, #{balanceAfter}, #{frozenBefore}, #{frozenAfter}, #{remark}
)
